const STATE={GOVERNED_CHART:['Confirmed','已确认'],SUPPORTED:['Confirmed','已确认'],QUALIFIED:['Read with conditions','有条件阅读'],BOUNDED_BY_UNKNOWN:['No strong conclusion yet','暂不作强判断'],ALTERNATIVES_OPEN:['No strong conclusion yet','暂不作强判断'],SCHOOL_VIEW_OPEN:['Different school readings','存在不同学派解释'],COUNTERBALANCED:['No strong conclusion yet','暂不作强判断'],PARTIAL:['No strong conclusion yet','暂不作强判断'],OPEN:['No strong conclusion yet','暂不作强判断']};
