const TREATMENT={SHUN_USE:['Supportive-use path','顺用'],NI_USE:['Counterbalancing-use path','逆用'],SPECIAL_JIANLU_YUEJIE_REVIEW:['Special Jian Lu / Month-Rob review','建禄／月劫特别核对']};
const RELATION={BRANCH_CLASH:['Clash','冲'],BRANCH_COMBINATION:['Combination','六合'],BRANCH_SIX_COMBINATION:['Six-combination','六合'],BRANCH_HARM:['Harm','害'],BRANCH_BREAK:['Break','破'],BRANCH_PUNISHMENT_PAIR:['Punishment','刑'],BRANCH_PUNISHMENT_GROUP:['Three-punishment','三刑'],BRANCH_SELF_PUNISHMENT:['Self-punishment','自刑'],BRANCH_THREE_HARMONY:['Three-harmony','三合'],BRANCH_THREE_MEETING:['Three-meeting','三会'],BRANCH_THREE_HARMONY_WITH_LIU_NIAN:['Three-harmony structure','三合结构'],BRANCH_THREE_MEETING_WITH_LIU_NIAN:['Three-meeting structure','三会结构'],BRANCH_THREE_PUNISHMENT_WITH_LIU_NIAN:['Three-punishment structure','三刑结构'],STEM_COMBINATION:['Stem combination','天干合'],STEM_REPEAT:['Stem repeat','天干同见']};
const SCHOOL_SCOPE={ZI_PING_MONTH_COMMAND_USE_v1:['Month command, pattern formation and operative factor','月令、格局成败与作用因素'],DI_TIAN_SUI_TI_YONG_BALANCE_v1:['Whole-chart weighting and structural balance','整盘偏重、体用与结构平衡'],DI_TIAN_SUI_CLIMATE_TIAOHOU_v1:['Cold / warm / dry / wet climate adjustment','寒暖燥湿的调候维度']};

