function ensureBaziSpecialistCss(){if(typeof document==='undefined')return;const href=BAZI_SPECIALIST_CSS;if(document.querySelector(`link[data-ppr-bazi-specialist-css="true"]`))return;const link=document.createElement('link');link.rel='stylesheet';link.href=href;link.dataset.pprBaziSpecialistCss='true';document.head?.appendChild(link)}
function graphNodeLabel(key){const x=GRAPH_NODE_LABELS[key];return x?tr(x[0],x[1]):String(key||'')}
function graphNodeCopy(key){const x=GRAPH_NODE_COPY[key];return x?tr(x[0],x[1]):''}
function graphCard(node){return `<article class="cx-bazi-graph-node" data-node="${esc(node.nodeKey||'')}" data-state="${esc(node.trace?.resolutionState||'OPEN')}"><header><small>${esc(customerState(node.trace?.resolutionState))}</small><h4>${esc(graphNodeLabel(node.nodeKey))}</h4></header><p>${esc(graphNodeCopy(node.nodeKey))}</p></article>`}

const label=(map,key,fallback='')=>{const x=map[String(key||'').toUpperCase()];return x?tr(x[0],x[1]):fallback||String(key||'')};
const customerState=value=>label(STATE,value,tr('Open','仍待确认'));
const element=value=>label(ELEMENT,value,'—');
const polarity=value=>label(POLARITY,value,'—');
const position=value=>label(POSITION,value,'—');
const hiddenText=item=>{const stem=item?.stemZh||'—';const tg=tr(item?.tenGodEn||item?.tenGodZh||'',item?.tenGodZh||item?.tenGodEn||'');return tg?`${stem} · ${tg}`:stem};
const STEM_ZH=Object.freeze({JIA:'甲',YI:'乙',BING:'丙',DING:'丁',WU:'戊',JI:'己',GENG:'庚',XIN:'辛',REN:'壬',GUI:'癸'});
const BRANCH_ZH=Object.freeze({ZI:'子',CHOU:'丑',YIN:'寅',MAO:'卯',CHEN:'辰',SI:'巳',WU:'午',WEI:'未',SHEN:'申',YOU:'酉',XU:'戌',HAI:'亥'});
const customerText=value=>String(value??'').replace(/\b(JIA|YI|BING|DING|WU|JI|GENG|XIN|REN|GUI|ZI|CHOU|YIN|MAO|CHEN|SI|WEI|SHEN|YOU|XU|HAI)\b/g,code=>BRANCH_ZH[code]||STEM_ZH[code]||code).replace(/Full Production/gi,'').replace(/Reading IR/gi,tr('current chart reading','当前命盘解读')).replace(/semantic owners?/gi,tr('whole-chart themes','整盘主题')).replace(/\badmitted\b/gi,tr('established','已建立')).replace(/\bauthority\b/gi,tr('source basis','来源依据')).replace(/\bgoverned\b/gi,tr('current','当前')).replace(/已准入/g,'已建立').replace(/准入/g,'确认').replace(/受治理/g,'当前').replace(/权威/g,'来源依据').replace(/语义\s*owner/gi,'整盘主题').replace(/\bW\d+[A-Z0-9.-]*\b/gi,'').replace(/\s{2,}/g,' ').trim();
const branchZh=value=>BRANCH_ZH[String(value||'').toUpperCase()]||String(value||'');

export function isBaziNativeProduct(product){return product?.schemaVersion==='PHI-OS-METHOD-NATIVE-CUSTOMER-READING-v1.0.0'&&product?.methodId==='BZR'&&product?.publicationDecision?.customerPublishable===true}

function pillarCard(pillar){
 const stem=pillar?.stem||{},branch=pillar?.branch||{},role=pillar?.stemRole||{};
 const isDay=pillar?.position==='DAY',isMonth=pillar?.position==='MONTH';
 const roleText=tr(role.tenGodEn||role.tenGodZh||'',role.tenGodZh||role.tenGodEn||'');
 return `<article class="cx-bazi-pillar" data-pillar="${esc(pillar?.position||'')}"${isDay?' data-day-master="true"':''}${isMonth?' data-month-command="true"':''}><header><span>${esc(position(pillar?.position))}</span>${isDay?`<em>${esc(tr('Day Master','日主'))}</em>`:isMonth?`<em>${esc(tr('Month command','月令'))}</em>`:''}</header><div class="cx-bazi-pillar__stem"><small>${esc(roleText||tr('Heavenly stem','天干'))}</small><strong>${esc(stem.zh||'—')}</strong><span>${esc([element(stem.element),polarity(stem.polarity)].filter(Boolean).join(' · '))}</span></div><div class="cx-bazi-pillar__branch"><small>${esc(tr('Earthly branch','地支'))}</small><strong>${esc(branch.zh||'—')}</strong><span>${esc(element(branch.element))}</span></div><div class="cx-bazi-pillar__hidden"><small>${esc(tr('Hidden stems','藏干'))}</small>${arr(pillar?.hiddenStems).length?`<ul>${arr(pillar.hiddenStems).map(x=>`<li>${esc(hiddenText(x))}</li>`).join('')}</ul>`:`<span>—</span>`}</div></article>`;
}

function wholeChartFacts(product){
 const pillars=arr(product?.structuralModel?.pillars),day=pillars.find(x=>x.position==='DAY'),month=pillars.find(x=>x.position==='MONTH');
 const relationships=arr(product?.readingSections).find(x=>x.code==='RELATIONSHIPS');
 const pattern=arr(product?.readingSections).find(x=>x.code==='PATTERNS');
 return {day,month,relationshipText:arr(relationships?.paragraphs)[0]||tr('No additional natal relation was established in this run.','本次没有建立额外的原局关系。'),patternText:arr(pattern?.paragraphs)[0]||tr('Pattern verdict remains open.','格局判断保持开放。'),openCount:arr(product?.openVerdicts).length};
}

export function renderBaziProfessionalStructure(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const pillars=arr(product?.structuralModel?.pillars),facts=wholeChartFacts(product),day=facts.day?.stem||{},month=facts.month?.branch||{};
 return `<section class="cx-bazi-structure-surface${embedded?' cx-bazi-structure-surface--embedded':''}" data-ppr-bazi-professional-structure="true"><header class="cx-bazi-structure-head"><div><p class="cx-eyebrow">${esc(tr('YOUR FOUR PILLARS','你的四柱命盘'))}</p><h3>${esc(tr('Start with Day Master and month command, then read the four pillars together.','先抓住日主与月令，再把四柱放回同一张盘里看。'))}</h3><p>${esc(tr('Heavenly stems, Earthly branches, Ten-God roles and hidden stems stay visible so you can see where each part of the reading comes from.','天干、地支、十神角色与藏干都保留在盘面上，让你看得见每一层解释从哪里来。'))}</p></div></header><div class="cx-bazi-chart-facts"><article><small>${esc(tr('Day Master','日主'))}</small><strong>${esc(day.zh||'—')}</strong><span>${esc([element(day.element),polarity(day.polarity)].filter(Boolean).join(' · '))}</span></article><article><small>${esc(tr('Month command','月令'))}</small><strong>${esc(month.zh||'—')}</strong><span>${esc(element(month.element))}</span></article><article><small>${esc(tr('Natal relation','原局关系'))}</small><strong>${esc(customerText(facts.relationshipText))}</strong></article><article><small>${esc(tr('Pattern direction','格局方向'))}</small><strong>${esc(customerText(facts.patternText))}</strong></article></div><div class="cx-bazi-pillar-grid">${pillars.map(pillarCard).join('')}</div><footer><span>${esc(tr('How to read this chart','怎么看这张盘'))}</span><p>${esc(tr('A pillar tells you where a structure appears; its meaning comes from how Day Master, season, Five Elements, Ten Gods and relationships work together.','柱位告诉你结构出现在哪里；真正的意义要结合日主、季节、五行、十神与干支关系一起读。'))}</p></footer></section>`;
}

const ELEMENT_ORDER=['WOOD','FIRE','EARTH','METAL','WATER'];
const ELEMENT_ROLE={PEER:['Peers / self-support','同类／自我支持'],RESOURCE:['Resource / support','印星／吸收支持'],OUTPUT:['Output / expression','食伤／表达输出'],WEALTH:['Wealth / exchange','财星／资源交换'],OFFICER:['Officer / responsibility','官杀／规则责任'],UNAVAILABLE:['Role not resolved','功能待核对']};
const SEASON_RELATION={SAME_AS_MONTH_COMMAND:['Season anchor','与月令同气'],GENERATED_BY_MONTH_COMMAND:['Season can support it','受月令相生'],GENERATES_MONTH_COMMAND:['Feeds the month command','生助月令'],CONTROLLED_BY_MONTH_COMMAND:['Constrained by month command','受月令制约'],CONTROLS_MONTH_COMMAND:['Checks the month command','制约月令'],MONTH_COMMAND_RELATION_UNAVAILABLE:['Season relation open','季节关系待核对']};
const TEN_GOD_LABEL={BI_JIAN:['Peer','比肩'],JIE_CAI:['Rob Wealth','劫财'],SHI_SHEN:['Eating God','食神'],SHANG_GUAN:['Hurting Officer','伤官'],PIAN_CAI:['Indirect Wealth','偏财'],ZHENG_CAI:['Direct Wealth','正财'],QI_SHA:['Seven Killings','七杀'],ZHENG_GUAN:['Direct Officer','正官'],PIAN_YIN:['Indirect Resource','偏印'],ZHENG_YIN:['Direct Resource','正印']};
const elementRole=value=>label(ELEMENT_ROLE,value,tr('Role open','功能待核对'));
const seasonRelation=value=>label(SEASON_RELATION,value,tr('Season relation open','季节关系待核对'));
const tenGodLabel=value=>label(TEN_GOD_LABEL,value,String(value||'').replaceAll('_',' '));
const ELEMENT_SEASON_EXPLANATION={
 SAME_AS_MONTH_COMMAND:['It shares the month-command element, so the seasonal background makes it especially worth watching.','它与月令同气，因此季节背景会让这一五行更值得优先观察。'],
 GENERATED_BY_MONTH_COMMAND:['The month-command element generates it, so the seasonal background offers a supportive direction.','月令五行生助它，因此季节背景提供了支持方向。'],
 GENERATES_MONTH_COMMAND:['It generates the month-command element, so part of its structural presence feeds the seasonal environment.','它生助月令五行，因此这部分结构会向季节主气输出。'],
 CONTROLLED_BY_MONTH_COMMAND:['The month-command element controls it, so the same raw count should not be treated as equally effective without checking roots and the whole chart.','它受月令五行制约，因此即使原始数量不少，也不能不看根气与整盘就直接当作同等有效。'],
 CONTROLS_MONTH_COMMAND:['It controls the month-command element, showing a structural tension with the seasonal background that needs whole-chart context.','它制约月令五行，显示与季节主气之间存在结构张力，需要放回整盘继续判断。'],
 MONTH_COMMAND_RELATION_UNAVAILABLE:['The seasonal relationship is not strong enough to summarize yet.','当前还不足以把它与季节背景概括成更明确的关系。']
};
const elementReading=item=>{const x=ELEMENT_SEASON_EXPLANATION[item?.monthCommandRelation]||ELEMENT_SEASON_EXPLANATION.MONTH_COMMAND_RELATION_UNAVAILABLE;return tr(`${x[0]} Relative to the Day Master, it belongs to the ${elementRole(item?.dayMasterFunction)} functional family.`,`${x[1]} 相对日主，它属于「${elementRole(item?.dayMasterFunction)}」这一功能组。`)};
const TEN_GOD_GROUP_LABEL={PEER:['Peer / self-position','同类／自我位置'],OUTPUT:['Output / expression','输出／表达'],WEALTH:['Wealth / exchange','财星／资源交换'],OFFICER:['Officer / pressure','官杀／规则压力'],RESOURCE:['Resource / support','印星／吸收支持'],UNAVAILABLE:['To be clarified','待继续核对']};
const DAY_MASTER_RELATION_LABEL={PEER_SUPPORT:['Peer support','同类支持'],RESOURCE_SUPPORT:['Resource support','资源生扶'],OUTPUT_DRAIN:['Output / drain','泄'],CONTROLLED_BY_DAY_MASTER:['Consumption / wealth','耗'],PRESSURE_ON_DAY_MASTER:['Pressure / control','克'],UNAVAILABLE:['Open','待核对']};
const STRENGTH_TENDENCY={SUPPORT_SIDE_VISIBLE:['Support side more visible','承载与支持侧更明显'],OUTPUT_SIDE_VISIBLE:['Output and consumption side more visible','外泄与耗力侧更明显'],PRESSURE_SIDE_VISIBLE:['Pressure side more visible','受克与受压侧更明显'],MIXED_CARRY:['Support, drain and pressure are mixed','支持、外泄与压力并见']};
const SIGNAL_LABEL={DE_LING:['Seasonal support','得令'],DE_DI:['Grounded through branches','得地'],DE_ZHU:['Visible help','得助'],XIE:['Output drain','泄'],HAO:['Consumption / wealth draw','耗'],KE:['Pressure / control','克'],GEN_QI:['Roots','根气'],TOU_GAN:['Visible stems','透干']};
const groupLabel=value=>label(TEN_GOD_GROUP_LABEL,value,tr('To be clarified','待继续核对'));
const dayRelationLabel=value=>label(DAY_MASTER_RELATION_LABEL,value,tr('Open','待核对'));
const strengthTendencyLabel=value=>label(STRENGTH_TENDENCY,value,tr('Mixed carry','混合承载'));
const signalLabel=value=>label(SIGNAL_LABEL,value,tr('Signal','结构信号'));
const pillarInline=list=>arr(list).map(position).join('、');
const countPillars=(pillarCounts={})=>Object.entries(pillarCounts).filter(([,count])=>Number(count)>0).map(([pillar,count])=>`${position(pillar)}${count>1?`×${count}`:''}`).join('、');
function tenGodSourceSummary(item){if((Number(item?.count)||0)<=0)return tr('Not seen in the chart statistics for now.','原局统计里暂时未见。');const parts=[];if(Number(item?.visibleCount)||0)parts.push(tr(`${item.visibleCount} visible stem touch(es)`,`透干 ${item.visibleCount} 次`));if(Number(item?.hiddenCount)||0)parts.push(tr(`${item.hiddenCount} hidden-stem touch(es)`,`藏干 ${item.hiddenCount} 次`));const pillars=countPillars(item?.sources?.pillarCounts||{});if(pillars)parts.push(tr(`appearing in ${pillars}`,`分布于 ${pillars}`));return parts.join(tr(' · ',' · '));}
function tenGodConcentrationSummary(item){if((Number(item?.count)||0)<=0)return tr('No concentration to read because the chart does not show this Ten-God point here.','由于原局未见这个十神，这里没有集中度可读。');if(item?.repeatState==='SINGLE_TOUCH')return tr('It appears once, so it acts more like a single doorway than a repeated theme.','只出现 1 次，更像单一点入口，而不是反复主题。');const spread=pillarInline(arr(item?.concentration?.spreadPillars).map(x=>x.pillar));if(item?.concentration?.mode==='CONCENTRATED')return tr(`It repeats ${item.count} times and clusters mainly around ${spread||'a narrow pillar range'}.`,`共出现 ${item.count} 次，主要集中在 ${spread||'较少的柱位'}。`);if(item?.concentration?.mode==='SPREAD')return tr(`It repeats ${item.count} times across ${spread||'multiple pillars'}, so the theme is distributed rather than isolated.`,`共出现 ${item.count} 次，分布在 ${spread||'多个柱位'}，属于分散进入命盘的主题。`);return tr(`It repeats ${item.count} times with a balanced spread across ${spread||'the chart'}.`,`共出现 ${item.count} 次，在 ${spread||'整张盘'} 上较平均分布。`);}
function tenGodCustomerReading(item){if((Number(item?.count)||0)<=0)return tr('Its absence in the chart statistics does not mean the person lacks that life capacity forever; it only means this theme is not a foreground structural emphasis in the present chart layer.','原局统计未见，并不等于现实里永远没有这项能力，只表示这一层命盘结构里它不是前景重点。');const monthText=seasonRelation(item?.monthCommandRelation);const groupText=groupLabel(item?.functionGroup);const patternText=item?.monthCommandCandidate?tr('It also appears in the month-command pattern path, so it should be read together with seasonal and pattern conditions.','它同时进入月令格局路径，因此要和季节与格局条件一起读。'):tr('At this stage it is read mainly through its visible / hidden placement and the rest of the chart.','现阶段主要通过它的透干／藏干来源与整盘关系来读。');return tr(`This belongs to the ${groupText} family relative to the Day Master. Relative to the month command it is read as ${monthText}. ${patternText}`,`相对日主，它属于「${groupText}」这一功能组；相对月令，目前可读作「${monthText}」。${patternText}`);}
function transparentStemSummary(module){const groups=[['PEER_SUPPORT',tr('support','支持')],['RESOURCE_SUPPORT',tr('resource','生扶')],['OUTPUT_DRAIN',tr('output','泄')],['CONTROLLED_BY_DAY_MASTER',tr('consumption','耗')],['PRESSURE_ON_DAY_MASTER',tr('pressure','克')]];const parts=groups.map(([key,label])=>{const count=arr(module?.transparentStems?.byRelation?.[key]).length;return count?`${label} ${count}`:''}).filter(Boolean);return parts.length?parts.join(tr(' · ',' · ')):tr('No additional visible stems are available to summarise here.','这里没有更多可概括的透干结构。');}
function signalDescription(signal,module){switch(signal?.signalCode){case 'DE_LING':return signal?.count?tr('The month-command environment is on the support side of the Day Master, so seasonal carrying power is present.','月令环境站在日主的同类／生扶一侧，因此季节承载力存在。'):tr(`The month-command relation is ${seasonRelation(module?.seasonalSupport?.getLingState)}; this is not read as a direct 得令 structure.`,`月令关系目前是「${seasonRelation(module?.seasonalSupport?.getLingState)}」，不直接当作得令结构。`);case 'DE_DI':return module?.roots?.total?tr(`${module.roots.total} root record(s) are visible in the branches, so the Day Master is not floating without ground.`,`地支里可见 ${module.roots.total} 处根气，说明日主并不是完全无根浮动。`):tr('No root evidence is visible in the current branch layer, so grounding should not be assumed.','当前地支层没有看到根气记录，因此不能自动假设有根。');case 'DE_ZHU':return module?.supportBalance?.supportVisible?tr(`${module.supportBalance.supportVisible} visible support touch(es) stand on the Day Master side.`,`可见 ${module.supportBalance.supportVisible} 项生扶／同类落点站在日主一侧。`):tr('Visible support is limited, so help should not be overstated without more context.','可见生扶有限，因此不能过度放大外援或同类支持。');case 'XIE':return module?.supportBalance?.visibleCounts?.OUTPUT_DRAIN?tr(`${module.supportBalance.visibleCounts.OUTPUT_DRAIN} visible point(s) show outward release or expression from the Day Master.`,`可见 ${module.supportBalance.visibleCounts.OUTPUT_DRAIN} 项外泄／输出落点。`):tr('No strong output-drain emphasis is visible in this layer.','这一层没有明显的泄势重点。');case 'HAO':return module?.supportBalance?.visibleCounts?.CONTROLLED_BY_DAY_MASTER?tr(`${module.supportBalance.visibleCounts.CONTROLLED_BY_DAY_MASTER} visible point(s) show the Day Master spending energy to manage, exchange or allocate.`,`可见 ${module.supportBalance.visibleCounts.CONTROLLED_BY_DAY_MASTER} 项耗力去管理、交换或配置的落点。`):tr('No strong consumption-through-control emphasis is visible in this layer.','这一层没有明显的耗力重点。');case 'KE':return module?.supportBalance?.visibleCounts?.PRESSURE_ON_DAY_MASTER?tr(`${module.supportBalance.visibleCounts.PRESSURE_ON_DAY_MASTER} visible point(s) show standards, pressure or control acting on the Day Master.`,`可见 ${module.supportBalance.visibleCounts.PRESSURE_ON_DAY_MASTER} 项规则／压力作用于日主。`):tr('No strong pressure-on-Day-Master emphasis is visible in this layer.','这一层没有明显的受克重点。');case 'GEN_QI':return module?.roots?.exactDayStemCount?tr(`An exact root is visible, with ${module.roots.exactDayStemCount} direct root record(s).`,`可见日主本气根 ${module.roots.exactDayStemCount} 项。`):module?.roots?.sameElementCount?tr(`Same-element roots are visible even if an exact root is not foregrounded.`,`虽然未突出本气根，但可见同五行根气。`):tr('No root Qi is being claimed here.','这里不宣称存在根气。');case 'TOU_GAN':return module?.transparentStems?.count?tr(`${module.transparentStems.count} visible stem point(s) help show which themes come to the surface first.`,`共有 ${module.transparentStems.count} 项透干，帮助判断哪些主题先浮到表层。`):tr('No additional visible stems are exposed beyond the Day Master anchor.','除日主锚点外，没有更多透干结构可见。');default:return tr('This structural signal remains open.','这个结构信号保持开放。')}}
function rootSummary(module){if(!module?.roots?.total)return tr('The current root layer does not establish visible grounding for the Day Master.','当前根气层没有为日主建立可见的落地依据。');const pillars=pillarInline(arr(module?.roots?.sources).map(x=>x.pillar));const exact=Number(module?.roots?.exactDayStemCount)||0,same=Number(module?.roots?.sameElementCount)||0;return tr(`${module.roots.total} root record(s) are visible${pillars?` in ${pillars}`:''}. ${exact?`${exact} are exact roots. `:''}${same?`${same} are same-element roots.`:''}`.trim(),`共见 ${module.roots.total} 处根气${pillars?`，分布在 ${pillars}`:''}。${exact?`其中 ${exact} 处为本气根。`:''}${same?`另有 ${same} 处为同五行根。`:''}`.trim());}
function carryingSummary(module){const roots=Number(module?.roots?.total)||0,support=Number(module?.supportBalance?.supportVisible)||0,outward=Number(module?.supportBalance?.outwardVisible)||0,pressure=Number(module?.supportBalance?.pressureVisible)||0;return tr(`${strengthTendencyLabel(module?.carriers?.overallTendency)} · roots ${roots} · visible support ${support} · drain / consumption ${outward} · pressure ${pressure}. This shows carrying structure, not a simplified strong/weak score.`,`${strengthTendencyLabel(module?.carriers?.overallTendency)} · 根气 ${roots} · 可见生扶 ${support} · 泄／耗 ${outward} · 克 ${pressure}。这里展示的是承载结构，不是简化的身强身弱分数。`)}
export function renderBaziFiveElementSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const module=product?.professionalModules?.fiveElements,tenGods=product?.professionalModules?.tenGods;if(module?.schemaVersion!=='PHI-OS-BAZI-CX-PRO-FIVE-ELEMENT-VISUAL-PROJECTION-v1.0.0')return '';
 const items=arr(module.items),tenGodItems=arr(tenGods?.items).slice().sort((a,b)=>b.count-a.count||b.ratio-a.ratio);
 return `<section class="cx-bazi-five-element-surface${embedded?' cx-bazi-surface--embedded':''}" data-bazi-cx-pro-five-elements="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('FIVE ELEMENTS · STRUCTURE & SEASON','五行 · 结构占比与季节校正'))}</p><h3>${esc(tr('See what appears most often, then correct the first impression with the month command.','先看哪些五行出现得多，再用月令修正第一眼的判断。'))}</h3><p>${esc(tr('The bars are raw structural ratios, not strength scores. Seasonal correction is qualitative because this version does not invent hidden-stem weights or a fake weighted percentage.','彩色柱显示原始结构占比，不等同旺衰分数。季节校正采用定性关系，因为当前版本不会虚构藏干权重，也不会制造假的加权百分比。'))}</p></div><span class="cx-bazi-season-chip">${esc(tr('Month command','月令'))} · ${esc(module.monthCommand?.branchZh||'—')} · ${esc(element(module.monthCommand?.element))}</span></header><div class="cx-bazi-element-grid">${items.map(item=>`<article class="cx-bazi-element-card" data-element="${esc(item.element)}"><header><div><span class="cx-bazi-element-dot" aria-hidden="true"></span><h4>${esc(element(item.element))}</h4></div><strong>${esc(item.rawRatio)}%</strong></header><div class="cx-bazi-element-bar" role="img" aria-label="${esc(`${element(item.element)} ${item.rawRatio}%`)}"><i style="--bazi-element-ratio:${Math.max(0,Math.min(100,Number(item.rawRatio)||0))}%"></i></div><dl><div><dt>${esc(tr('Raw structure','原始结构'))}</dt><dd>${esc(tr(`${item.rawCount} appearances`,`出现 ${item.rawCount} 次`))}</dd></div><div><dt>${esc(tr('Seasonal tendency','校正倾向'))}</dt><dd>${esc(seasonRelation(item.monthCommandRelation))}</dd></div><div><dt>${esc(tr('Relative to Day Master','相对日主'))}</dt><dd>${esc(elementRole(item.dayMasterFunction))}</dd></div></dl><p class="cx-bazi-element-reading">${esc(elementReading(item))}</p><details><summary>${esc(tr('Where the raw count comes from','这个占比怎么来的'))}</summary><p>${esc(tr(`Visible stems ${item.breakdown?.visibleStems||0} · branches ${item.breakdown?.visibleBranches||0} · hidden stems ${item.breakdown?.hiddenStemsUnweighted||0}`,`显干 ${item.breakdown?.visibleStems||0} · 地支 ${item.breakdown?.visibleBranches||0} · 藏干 ${item.breakdown?.hiddenStemsUnweighted||0}`))}</p></details></article>`).join('')}</div><div class="cx-bazi-five-element-explainer"><article><small>${esc(tr('RAW RATIO','原始占比'))}</small><h4>${esc(tr('Useful for seeing composition, not for declaring strong or weak.','用来观察组成，不直接拿来判身强身弱。'))}</h4><p>${esc(tr('Visible stems, branch elements and hidden stems are counted equally in this first-layer view.','这一层把显干、地支五行与藏干等权统计，因此它回答“盘里出现了什么”，不是“谁的实际力量最大”。'))}</p></article><article><small>${esc(tr('SEASONAL CORRECTION','季节校正'))}</small><h4>${esc(tr('Month command changes how the same raw ratio should be read.','同一个原始占比，放到不同月令里意义会不同。'))}</h4><p>${esc(tr('The page shows whether each element shares, receives from, feeds, controls or is controlled by the month-command element. Final strength still needs roots and the whole chart.','页面标出各五行与月令是同气、受生、生助、制约或受制；最终旺衰仍要继续结合根气与整盘。'))}</p></article></div>${tenGods?.schemaVersion==='PHI-OS-BAZI-CX-PRO-TEN-GOD-PROFESSIONAL-COMPOSITION-v1.0.0'?`<section class="cx-bazi-ten-god-surface" data-bazi-cx-pro-ten-gods="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('TEN-GOD PREVIEW · PROFESSIONAL COMPOSITION','十神结构预览 · 专业组合阅读'))}</p><h3>${esc(tr('Read ratio, function group, source positions, repetition and chart integration together.','把占比、功能组、柱位来源、重复集中与整盘组合放在一起看。'))}</h3><p>${esc(tr('This is still a structural composition. It does not create good-bad scoring or simplified personality grading.','这里仍然是结构组合阅读，不制造吉凶评分，也不把人简化成人格打分。'))}</p></div><span class="cx-bazi-season-chip">${esc(tr(`${tenGods.totalTouches} Ten-God touches`,`${tenGods.totalTouches} 个十神落点`))}</span></header><div class="cx-bazi-ten-god-hero"><div class="cx-bazi-ten-god-column-grid">${tenGodItems.map(item=>`<article class="cx-bazi-ten-god-column" data-function-group="${esc(item.functionGroup)}" data-ten-god="${esc(item.tenGodCode)}"><div class="cx-bazi-ten-god-column-track"><i style="--bazi-ten-god-ratio:${Math.max(0,Math.min(100,Number(item.ratio)||0))}%"></i></div><strong>${esc(tenGodLabel(item.tenGodCode))}</strong><span>${esc(item.ratio)}%</span></article>`).join('')}</div><div class="cx-bazi-ten-god-hero-side"><article><small>${esc(tr('Day Master','日主'))}</small><strong>${esc(tenGods.dayMaster?.zh||'—')}</strong><p>${esc(tr('Ten-God meaning always returns to the Day Master as the reference point.','十神的意义始终回到日主作为参照。'))}</p></article><article><small>${esc(tr('Month command','月令'))}</small><strong>${esc(tenGods.monthCommand?.branchZh||'—')}</strong><p>${esc(tr('The month command changes which Ten-God themes come forward more easily.','月令会改变哪些十神主题更容易浮到前景。'))}</p></article><article><small>${esc(tr('How to use the ratios','怎么看占比'))}</small><strong>${esc(tr('Foreground structure','前景结构'))}</strong><p>${esc(tr('Ratios show which Ten-God points appear more often in visible stems and hidden stems.','占比告诉你哪些十神在透干与藏干里出现得更频密。'))}</p></article></div></div><div class="cx-bazi-ten-god-group-grid">${arr(tenGods.functionGroups).slice().sort((a,b)=>b.count-a.count||b.ratio-a.ratio).map(group=>`<article class="cx-bazi-ten-god-group-card" data-function-group="${esc(group.groupCode)}"><header><small>${esc(tr('Function group','功能组'))}</small><h4>${esc(groupLabel(group.groupCode))}</h4><strong>${esc(group.ratio)}%</strong></header><div class="cx-bazi-ten-god-group-bar"><i style="--bazi-ten-god-ratio:${Math.max(0,Math.min(100,Number(group.ratio)||0))}%"></i></div><p>${esc(tr(`${group.count} touch(es) across ${arr(group.tenGodCodes).map(tenGodLabel).join(' / ')}`,`${group.count} 个落点，包含 ${arr(group.tenGodCodes).map(tenGodLabel).join('／')}`))}</p></article>`).join('')}</div><div class="cx-bazi-ten-god-card-grid">${tenGodItems.map(item=>`<article class="cx-bazi-ten-god-card" data-function-group="${esc(item.functionGroup)}" data-ten-god="${esc(item.tenGodCode)}"><header><div><small>${esc(groupLabel(item.functionGroup))}</small><h4>${esc(tenGodLabel(item.tenGodCode))}</h4></div><strong>${esc(item.ratio)}%</strong></header><div class="cx-bazi-ten-god-card-bar"><i style="--bazi-ten-god-ratio:${Math.max(0,Math.min(100,Number(item.ratio)||0))}%"></i></div><dl><div><dt>${esc(tr('Pillar / source','柱位与来源'))}</dt><dd>${esc(tenGodSourceSummary(item))}</dd></div><div><dt>${esc(tr('Repetition / concentration','重复与集中'))}</dt><dd>${esc(tenGodConcentrationSummary(item))}</dd></div><div><dt>${esc(tr('Season / pattern connection','月令与格局连接'))}</dt><dd>${esc(tr(`${seasonRelation(item.monthCommandRelation)}${item.monthCommandCandidate?' · in current month-command pattern path':''}`,`${seasonRelation(item.monthCommandRelation)}${item.monthCommandCandidate?' · 已进入当前月令格局路径':''}`))}</dd></div></dl><p class="cx-bazi-ten-god-note">${esc(tenGodCustomerReading(item))}</p></article>`).join('')}</div></section>`:''}</section>`;
}

export function renderBaziDayMasterStrengthSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const module=product?.professionalModules?.dayMasterStrength;if(module?.schemaVersion!=='PHI-OS-BAZI-CX-PRO-DAY-MASTER-STRENGTH-PROFESSIONAL-COMPOSITION-v1.0.0')return '';
 const support=Math.max(0,Number(module?.supportBalance?.supportTotal)||0),outward=Math.max(0,Number(module?.supportBalance?.outwardVisible)||0),pressure=Math.max(0,Number(module?.supportBalance?.pressureVisible)||0),total=Math.max(1,support+outward+pressure);
 return `<section class="cx-bazi-day-master-strength${embedded?' cx-bazi-surface--embedded':''}" data-bazi-cx-pro-day-master-strength="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('DAY MASTER · SEASON · CARRYING STRUCTURE','日主 · 月令 · 承载结构'))}</p><h3>${esc(tr('Split support, drain and pressure before saying anything about strong or weak.','先把支持、外泄与压力拆开看，再谈承载结构。'))}</h3><p>${esc(tr('This section keeps 得令、得地、得助、泄、耗、克、根气 and visible stems visible at the same time. It shows structure, not a simplified strong/weak sticker.','这一章把得令、得地、得助、泄、耗、克、根气与透干同时摆出来看；它展示的是结构，不是简单贴一个身强／身弱标签。'))}</p></div><span class="cx-bazi-season-chip">${esc(module.dayMaster?.zh||'—')} · ${esc(tr('Day Master','日主'))} / ${esc(module.monthCommand?.branchZh||'—')} · ${esc(tr('Month command','月令'))}</span></header><div class="cx-bazi-strength-balance-card"><div><div class="cx-bazi-strength-balance-head"><small>${esc(tr('Overall carrying tendency','整体承载倾向'))}</small><strong>${esc(strengthTendencyLabel(module?.carriers?.overallTendency))}</strong></div><p>${esc(carryingSummary(module))}</p></div><div class="cx-bazi-strength-balance-bar" role="img" aria-label="${esc(tr(`support ${support}, outward ${outward}, pressure ${pressure}`,`支持 ${support}，泄耗 ${outward}，压力 ${pressure}`))}"><i data-balance="support" style="--bazi-strength-ratio:${support/total*100}%"></i><i data-balance="outward" style="--bazi-strength-ratio:${outward/total*100}%"></i><i data-balance="pressure" style="--bazi-strength-ratio:${pressure/total*100}%"></i></div><div class="cx-bazi-strength-balance-legend"><span data-balance="support">${esc(tr(`Support ${support}`,`支持 ${support}`))}</span><span data-balance="outward">${esc(tr(`Drain / consume ${outward}`,`泄耗 ${outward}`))}</span><span data-balance="pressure">${esc(tr(`Pressure ${pressure}`,`受克 ${pressure}`))}</span></div></div><div class="cx-bazi-strength-signal-grid">${arr(module.signals).map(signal=>`<article class="cx-bazi-strength-signal-card" data-signal="${esc(signal.signalCode)}"><header><small>${esc(tr('Signal','结构信号'))}</small><h4>${esc(signalLabel(signal.signalCode))}</h4><strong>${esc(signal.count)}</strong></header><p>${esc(signalDescription(signal,module))}</p></article>`).join('')}</div><div class="cx-bazi-strength-detail-grid"><article class="cx-bazi-strength-detail-card"><header><small>${esc(tr('Roots / 根气','根气'))}</small><h4>${esc(tr('Where the Day Master is rooted','日主从哪里落地'))}</h4></header><p>${esc(rootSummary(module))}</p></article><article class="cx-bazi-strength-detail-card"><header><small>${esc(tr('Visible stems / 透干','透干'))}</small><h4>${esc(tr('What comes to the surface first','哪些主题先浮到表层'))}</h4></header><p>${esc(transparentStemSummary(module))}</p></article></div><aside class="cx-bazi-strength-boundary"><strong>${esc(tr('Reading boundary','解释边界'))}</strong><p>${esc(tr('Supportive, draining and pressuring structures are shown separately on purpose. The page does not collapse them into a fake weighted score or a single unqualified strong/weak label.','页面刻意把生扶、外泄与受压拆开显示，不会把它们压成一个假的加权分数，也不会直接折叠成单一、无条件的身强身弱标签。'))}</p></aside></section>`;
}


const RELATION_FAMILY_LABEL={LINK:['Link','联结'],TENSION:['Tension','张力'],GROUP_LINK:['Group link','群组联结'],GROUP_TENSION:['Group tension','群组张力'],REPEAT_TENSION:['Repeated tension','重复张力'],STRUCTURAL:['Structural relation','结构关系']};
const POSITION_THEME_LABEL={OUTER_ENVIRONMENT_INTERFACE:['Outer context ↔ month environment','外部背景 ↔ 月令环境'],OUTER_SELF_INTERFACE:['Outer context ↔ self anchor','外部背景 ↔ 自我锚点'],OUTER_EXPRESSION_INTERFACE:['Outer context ↔ outward expression','外部背景 ↔ 后续表达'],ENVIRONMENT_SELF_INTERFACE:['Month environment ↔ self anchor','月令环境 ↔ 自我锚点'],ENVIRONMENT_EXPRESSION_INTERFACE:['Month environment ↔ outward expression','月令环境 ↔ 后续表达'],SELF_EXPRESSION_INTERFACE:['Self anchor ↔ outward expression','自我锚点 ↔ 后续表达'],MULTI_PILLAR_NETWORK:['Multi-pillar network','多柱网络'],PILLAR_INTERFACE:['Pillar interface','柱位接口']};
const RELATION_THEME_LABEL={VISIBLE_STEM_LINK:['Visible-role connection','表层角色联结'],BRANCH_LINK:['Branch-level connection','地支层联结'],DIRECT_TENSION:['Direct structural tension','直接结构张力'],INDIRECT_FRICTION:['Indirect friction','间接牵扯'],STRUCTURAL_DISRUPTION:['Structural disruption','结构断续'],CONSTRAINT_PATTERN:['Constraint pattern','约束型张力'],MULTI_PILLAR_CONSTRAINT:['Multi-pillar constraint','多柱约束网络'],REPEATED_INTERNAL_TENSION:['Repeated internal tension','重复自刑结构'],THREE_PILLAR_ALIGNMENT:['Three-pillar alignment','三柱合局结构'],THREE_PILLAR_GATHERING:['Three-pillar gathering','三柱会局结构'],STRUCTURAL_RELATION:['Structural relation','结构关系']};
const RELATION_PRIORITY_LABEL={DAY_MASTER_MONTH_COMMAND_DIRECT:['Day Master + month command direct','日主 × 月令直接接口'],DAY_MASTER_DIRECT:['Direct to Day Master','直接触及日主'],MONTH_COMMAND_DIRECT:['Direct to month command','直接触及月令'],MULTI_PILLAR_NETWORK:['Multi-pillar network','多柱网络'],SECONDARY_INTERFACE:['Secondary pillar interface','次级柱位接口']};
const relationFamilyLabel=value=>label(RELATION_FAMILY_LABEL,value,tr('Structural relation','结构关系'));
const positionThemeLabel=value=>label(POSITION_THEME_LABEL,value,tr('Pillar interface','柱位接口'));
const relationThemeLabel=value=>label(RELATION_THEME_LABEL,value,tr('Structural relation','结构关系'));
const relationPriorityLabel=value=>label(RELATION_PRIORITY_LABEL,value,tr('Pillar interface','柱位接口'));
function relationContextText(item){const visible=arr(item?.context?.visibleTenGods).map(x=>x.zh||tenGodLabel(x.code)),hidden=arr(item?.context?.hiddenTenGodCodes).map(tenGodLabel),groups=arr(item?.context?.functionGroups).map(groupLabel);const bits=[];if(visible.length)bits.push(tr(`visible Ten Gods ${visible.join(' / ')}`,`透干十神 ${visible.join('／')}`));if(hidden.length)bits.push(tr(`hidden Ten Gods ${hidden.join(' / ')}`,`藏干十神 ${hidden.join('／')}`));if(groups.length)bits.push(tr(`functional groups ${groups.join(' / ')}`,`功能组 ${groups.join('／')}`));return bits.length?bits.join(tr(' · ',' · ')):tr('No additional Ten-God context is exposed for this interface.','这个接口目前没有更多十神上下文可展开。')}
function relationshipReading(item){const relationName=relation(item?.type),positions=arr(item?.positions).map(position).join(' ↔ '),theme=positionThemeLabel(item?.positionThemeCode),family=relationFamilyLabel(item?.relationFamily);const direct=item?.dayMasterDirect&&item?.monthCommandDirect?tr('Because this relation directly connects the Day Master position with the month-command position, it should be read together with both the seasonal background and the Day Master carrying structure.','因为这条关系直接连接日主位置与月令位置，所以要同时结合季节背景与日主承载结构。'):item?.dayMasterDirect?tr('Because the Day Master position is directly involved, the relation should be read together with roots, visible support, drain/consumption and pressure.','因为日主位置直接参与，所以这条关系要和根气、可见生扶、泄耗与受压一起读。'):item?.monthCommandDirect?tr('Because the month-command position is directly involved, seasonal context should stay visible when this relation is interpreted.','因为月令位置直接参与，所以解释这条关系时要保留季节背景。'):tr('This relation sits between other pillar positions and changes the structural context around the chart rather than replacing the Day Master as the reference point.','这条关系发生在其他柱位之间，主要改变整盘的结构语境，而不会取代日主作为参照。');return tr(`${relationName} connects ${positions} as a ${family} structure. The useful theme is ${theme}. ${direct}`,`${relationName}连接 ${positions}，属于「${family}」结构；较适合从「${theme}」这个接口进入阅读。${direct}`)}
function carryingBridgeText(item){if(!item?.dayMasterDirect)return tr('Day Master carrying structure is an indirect reference here.','这里以日主承载结构作为间接参照。');return tr(`Day Master carrying context: ${strengthTendencyLabel(item?.context?.dayMasterCarryingTendency)} · visible support ${item?.context?.supportVisible??0} · drain/consumption ${item?.context?.outwardVisible??0} · pressure ${item?.context?.pressureVisible??0} · roots in involved pillars ${item?.context?.rootCount??0}.`,`日主承载背景：${strengthTendencyLabel(item?.context?.dayMasterCarryingTendency)} · 可见生扶 ${item?.context?.supportVisible??0} · 泄耗 ${item?.context?.outwardVisible??0} · 克 ${item?.context?.pressureVisible??0} · 相关柱位根气 ${item?.context?.rootCount??0}。`)}
function themeReading(theme){const families=arr(theme?.relationFamilies).map(relationFamilyLabel).join('／'),gods=arr(theme?.tenGodCodes).map(tenGodLabel).join('／');const direct=theme?.dayMasterDirect&&theme?.monthCommandDirect?tr('This theme directly crosses both the Day Master and month-command anchors.','这个主题同时跨过日主与月令两个锚点。'):theme?.dayMasterDirect?tr('This theme directly touches the Day Master anchor.','这个主题直接触及日主锚点。'):theme?.monthCommandDirect?tr('This theme directly touches the month-command anchor.','这个主题直接触及月令锚点。'):tr('This theme works through the surrounding pillar network.','这个主题主要通过周边柱位网络发生作用。');return tr(`${theme.relationCount} relation(s) · ${families||'structural relation'}${gods?` · Ten Gods ${gods}`:''}. ${direct}`,`${theme.relationCount} 条关系 · ${families||'结构关系'}${gods?` · 十神 ${gods}`:''}。${direct}`)}
export function renderBaziRelationshipInteractionSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const module=product?.professionalModules?.relationships;if(module?.schemaVersion!=='PHI-OS-BAZI-CX-PRO-RELATIONSHIP-PILLAR-INTERACTION-v1.0.0')return '';
 const items=arr(module.items),pillars=arr(module.pillarContexts),themes=arr(module.themes);
 return `<section class="cx-bazi-relationship-professional${embedded?' cx-bazi-surface--embedded':''}" data-bazi-cx-pro-relationships="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('RELATIONSHIPS · PILLAR INTERACTION','关系结构 · 柱位互动'))}</p><h3>${esc(tr('Put combinations, clashes, punishments, harms and breaks back into the four-pillar network.','把合、冲、刑、害、破放回四柱网络里读，而不是只列一个关系名称。'))}</h3><p>${esc(tr('Each relation is connected to its pillar interface, Ten-God context and Day-Master carrying structure. Presence is structural evidence only; it is not an event prediction.','每条关系都会连接柱位接口、十神上下文与日主承载结构；关系出现只代表结构证据，不直接等同现实事件。'))}</p></div><span class="cx-bazi-season-chip">${esc(tr(`${module.summary?.relationCount||0} natal relation(s)`,`${module.summary?.relationCount||0} 条原局关系`))}</span></header><div class="cx-bazi-pillar-interaction-rail">${pillars.map(p=>`<article data-pillar="${esc(p.position)}"${p.isDayMaster?' data-day-master="true"':''}${p.isMonthCommand?' data-month-command="true"':''}><header><span>${esc(position(p.position))}</span>${p.isDayMaster?`<em>${esc(tr('Day Master','日主'))}</em>`:p.isMonthCommand?`<em>${esc(tr('Month command','月令'))}</em>`:''}</header><strong>${esc(`${p.stem?.zh||'—'}${p.branch?.zh||'—'}`)}</strong><p>${esc(p.visibleTenGod?.code?`${tenGodLabel(p.visibleTenGod.code)} · ${groupLabel(p.visibleTenGod.functionGroup)}`:tr('Day Master anchor','日主锚点'))}</p>${arr(p.hiddenTenGodCodes).length?`<small>${esc(tr('Hidden','藏干'))} · ${esc(arr(p.hiddenTenGodCodes).map(tenGodLabel).join('／'))}</small>`:''}${p.rootCount?`<small>${esc(tr(`Roots ${p.rootCount}`,`根气 ${p.rootCount}`))}</small>`:''}</article>`).join('')}</div>${items.length?`<div class="cx-bazi-relation-card-grid">${items.map((item,index)=>`<article class="cx-bazi-relation-card" data-relation-family="${esc(item.relationFamily)}" data-priority="${esc(item.priorityBand)}"><header><div><small>${String(index+1).padStart(2,'0')} · ${esc(relationPriorityLabel(item.priorityBand))}</small><h4>${esc(relation(item.type))} · ${esc(relationThemeLabel(item.relationThemeCode))}</h4></div><span>${esc(relationFamilyLabel(item.relationFamily))}</span></header><div class="cx-bazi-relation-members"><strong>${esc(memberText(item.members,item.type)||arr(item.memberZh).join(' ↔ ')||'—')}</strong><span>${esc(arr(item.positions).map(position).join(' ↔ '))}</span></div><div class="cx-bazi-relation-theme"><small>${esc(tr('Relationship theme','关系主题'))}</small><strong>${esc(positionThemeLabel(item.positionThemeCode))}</strong><p>${esc(relationshipReading(item))}</p></div><dl><div><dt>${esc(tr('Ten-God context','十神上下文'))}</dt><dd>${esc(relationContextText(item))}</dd></div><div><dt>${esc(tr('Day-Master carrying bridge','日主承载连接'))}</dt><dd>${esc(carryingBridgeText(item))}</dd></div></dl><footer>${esc(tr('Relation present ≠ transformation established ≠ event outcome.','关系出现 ≠ 合化成立 ≠ 现实事件结果。'))}</footer></article>`).join('')}</div>`:`<article class="cx-bazi-relationship-empty"><strong>${esc(tr('No covered natal relationship is foregrounded in this chart.','当前已覆盖规则里，没有需要前景化的原局合冲刑害破关系。'))}</strong><p>${esc(tr('This does not mean the chart has no relationship dynamics; it only means no relation in the current covered structural registry was detected.','这不代表命盘完全没有互动，只表示当前已覆盖结构规则里没有检测到对应关系。'))}</p></article>`}${themes.length?`<section class="cx-bazi-relationship-theme-section"><header><small>${esc(tr('THEME NAVIGATION','关系主题导航'))}</small><h4>${esc(tr('Which pillar interfaces deserve attention first?','哪些柱位接口值得优先看？'))}</h4></header><div>${themes.map(theme=>`<article><span>${esc(positionThemeLabel(theme.themeCode))}</span><strong>${esc(theme.relationCount)}</strong><p>${esc(themeReading(theme))}</p></article>`).join('')}</div></section>`:''}<aside class="cx-bazi-strength-boundary"><strong>${esc(tr('Interpretation boundary','解释边界'))}</strong><p>${esc(tr('Pillar themes organize where to look. They do not turn Year / Month / Day / Hour positions into deterministic labels for parents, spouse, children, career or specific events.','柱位主题只负责组织阅读入口，不会把年／月／日／时柱直接等同父母、配偶、子女、事业或具体事件的决定论标签。'))}</p></aside></section>`;
}

function patternFamily(value){return label(PATTERN_FAMILY,value,String(value||''))}
function treatment(value){return label(TREATMENT,value,String(value||''))}
function relation(value){return label(RELATION,value,String(value||'').replaceAll('_',' '))}
function pillarName(code){return position(code)}
function memberText(values,type=''){const branch=String(type).startsWith('BRANCH_');return arr(values).map(code=>(branch?BRANCH_ZH[code]:STEM_ZH[code])||BRANCH_ZH[code]||STEM_ZH[code]||code).join(' · ')}
function scopeForSchool(code){const x=SCHOOL_SCOPE[code];return x?tr(x[0],x[1]):tr('A separate school-qualified lens','独立的学派视角')}
function schoolOpenText(view){if(!arr(view?.unknownRefs).length)return tr('No additional open condition is recorded for this view.','这个视角没有额外未决条件。');if(view?.schoolCode==='ZI_PING_MONTH_COMMAND_USE_v1')return tr('The final operative-factor / useful-god selection remains open.','最终作用因素／用神选择仍开放。');if(view?.schoolCode==='DI_TIAN_SUI_TI_YONG_BALANCE_v1')return tr('The strong/weak verdict and final structural priority remain open.','身强身弱与最终优先顺序仍开放。');if(view?.schoolCode==='DI_TIAN_SUI_CLIMATE_TIAOHOU_v1')return tr('The final climate-adjustment element remains open.','最终调候元素仍开放。');return tr('This school-qualified conclusion remains open.','这个分学派结论仍开放。')}
function schoolEvidence(view){const e=view?.evidence||{};if(view?.schoolCode==='ZI_PING_MONTH_COMMAND_USE_v1')return tr(`Month command ${e.monthCommandBranch||'—'} · ${arr(e.patternCandidateIds).length} pattern paths · ${e.variationEvidencePresent?'variation conditions are visible':'variation conditions still need checking'}`,`月令 ${branchZh(e.monthCommandBranch)||'—'} · ${arr(e.patternCandidateIds).length} 条格局路径 · ${e.variationEvidencePresent?'已经看到变化条件':'变化条件仍要继续核对'}`);if(view?.schoolCode==='DI_TIAN_SUI_TI_YONG_BALANCE_v1')return tr(`${e.rootEvidenceCount??0} root record(s) · strong/weak ${e.strongWeakVerdictAvailable?'can be read':'still needs checking'}`,`${e.rootEvidenceCount??0} 项根气记录 · 身强身弱${e.strongWeakVerdictAvailable?'可以继续阅读':'仍要继续核对'}`);if(view?.schoolCode==='DI_TIAN_SUI_CLIMATE_TIAOHOU_v1')return tr(`Season ${e.season||'—'} · thermal ${e.thermalContext||'open'} · moisture ${e.moistureContext||'open'}`,`季节 ${e.season==='SPRING'?'春':e.season||'—'} · 寒暖 ${e.thermalContext==='TRANSITIONAL_SEASON_CONTEXT'?'过渡季节情境':e.thermalContext||'继续核对'} · 燥湿 ${e.moistureContext==='NOT_DECIDABLE_FROM_SEASON_ALONE'?'不能只由季节决定':e.moistureContext||'继续核对'}`);return tr('This school view is read from the same chart through a different technical question.','这个学派从同一张命盘提出不同的技术问题。')}

export function renderBaziPatternSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const m=product?.professionalModules?.pattern;if(!m)return '';
 return `<section class="cx-bazi-pattern-surface${embedded?' cx-bazi-surface--embedded':''}" data-ppr-bazi-pattern-professional="true" data-w15-section="PATTERNS"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('PATTERN · FORMATION / DEFEAT / RESCUE','格局 · 成败救应'))}</p><h3>${esc(tr('Compare the pattern paths on the same chart before naming a primary pattern.','把格局候选放回同一张命盘核对，再决定是否足以定主格。'))}</h3><p>${esc(tr('Each candidate is read through Support, Defeat, Rescue and Unresolved conditions. A missing condition stays missing instead of being filled by a generic rule.','每条候选都从支持、败格、救应与未决四面核对；本盘没有出现的条件，不会因为理论上存在就自动补上。'))}</p></div><span class="cx-personal-status-chip" data-state="open">${esc(customerState(m.state))}</span></header><div class="cx-bazi-pattern-grid">${arr(m.candidates).map(c=>`<article class="cx-bazi-pattern-card"><header><small>${esc(tr(`Month-command hidden stem ${c.hiddenOrder}`,`月令藏干第 ${c.hiddenOrder} 位`))}</small><h4>${esc(`${c.tenGodZh||'—'} · ${patternFamily(c.patternFamily)}`)}</h4><p>${esc(`${c.hiddenStemZh||'—'} · ${treatment(c.treatmentClass)}`)}</p></header><div class="cx-bazi-condition-grid"><section data-condition="support"><strong>${esc(tr('Support','支持'))}</strong><p>${esc(c.visibleStemMatch?tr(`The same stem appears in ${arr(c.visiblePillars).map(pillarName).join(', ')}.`,`同干透出于${arr(c.visiblePillars).map(pillarName).join('、')}。`):tr('The same stem does not appear among the four visible stems.','四个显干中没有同干透出。'))}</p></section><section data-condition="defeat"><strong>${esc(tr('Defeat','败格'))}</strong><p>${esc(tr('This chart has not established a specific defeat condition for this candidate.','当前命盘尚未建立这条候选的具体败格条件。'))}</p></section><section data-condition="rescue"><strong>${esc(tr('Rescue','救应'))}</strong><p>${esc(tr('This chart has not established a specific rescue condition for this candidate.','当前命盘尚未建立这条候选的具体救应条件。'))}</p></section><section data-condition="unresolved"><strong>${esc(tr('Unresolved','未决'))}</strong><p>${esc(c.priorityVerdict?tr('A clearer priority is available.','已经出现较清楚的优先顺序。'):tr('This candidate is not yet strong enough to become the single primary pattern.','目前还不足以把这条候选提升为唯一主格。'))}</p></section></div></article>`).join('')}</div><aside class="cx-bazi-professional-boundary"><strong>${esc(tr('Why the pattern may stay open','为什么暂时不唯一命名'))}</strong><p>${esc(tr('When several candidates remain plausible, the useful answer is to show what supports or weakens each path. A stronger primary pattern is stated only when the whole chart gives a clearer priority.','当多条候选都还有成立空间时，更有用的是看清每条路径被什么支持、又被什么削弱；只有整盘形成更清楚的优先顺序时，才会把其中一条提升为主格。'))}</p></aside></section>`;
}

export function renderBaziSchoolSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const schools=arr(product?.professionalModules?.schools);if(!schools.length)return '';
 return `<section class="cx-bazi-school-surface${embedded?' cx-bazi-surface--embedded':''}" data-ppr-bazi-school-professional="true" data-w15-section="SCHOOLS"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('THREE SCHOOLS · KEPT DISTINCT','三套学派 · 分开阅读'))}</p><h3>${esc(tr('Three schools can ask different questions of the same chart without being forced into one answer.','同一张命盘可以从三种技术视角阅读，不必硬把它们揉成一个答案。'))}</h3><p>${esc(tr('Differences are shown as different reading angles, not as an internal status problem.','学派差异会直接解释成不同阅读角度，而不是让客户面对内部状态语言。'))}</p></div><span class="cx-personal-status-chip" data-state="school">${esc(tr('Different school readings','存在不同学派解释'))}</span></header><div class="cx-bazi-school-professional-grid">${schools.map(v=>`<article class="cx-bazi-school-card"><header><span>${esc(customerState(v.resolutionState))}</span><h4>${esc(customerText(v.customerTitle||scopeForSchool(v.schoolCode)))}</h4></header><dl><div><dt>${esc(tr('What this school examines','这个学派在看什么'))}</dt><dd>${esc(scopeForSchool(v.schoolCode))}</dd></div><div><dt>${esc(tr('What this chart currently shows','这张盘目前看到了什么'))}</dt><dd>${esc(schoolEvidence(v))}</dd></div><div><dt>${esc(tr('How to read it now','目前可以怎么理解'))}</dt><dd>${esc(customerText(v.customerText||tr('This view still needs more chart-level support before a stronger conclusion.','这个视角仍要结合更多整盘条件，暂不作更强判断。')))}</dd></div><div><dt>${esc(tr('What still needs checking','还要继续核对什么'))}</dt><dd>${esc(schoolOpenText(v))}</dd></div></dl></article>`).join('')}</div></section>`;
}

function interactionList(items,emptyText){return arr(items).length?`<ul>${arr(items).map(x=>`<li><strong>${esc(relation(x.type))}</strong><span>${esc(memberText(x.members,x.type))}${x.natalPosition?` · ${esc(pillarName(x.natalPosition))}`:''}</span></li>`).join('')}</ul>`:`<p class="cx-bazi-muted">${esc(emptyText)}</p>`}
export function renderBaziTimingSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const t=product?.professionalModules?.timing;if(!t)return '';
 const current=t.currentDaYun,annual=t.annual,ix=t.interactions||{};
 return `<section class="cx-bazi-timing-surface${embedded?' cx-bazi-surface--embedded':''}" data-ppr-bazi-temporal-experience="true" data-w15-section="TIMING"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('NATAL × DA YUN × LIU NIAN','原局 × 大运 × 流年'))}</p><h3>${esc(tr('Read timing as structural activation, not as an event promise.','把时间层读成结构激活，而不是事件保证。'))}</h3></div><span class="cx-personal-status-chip" data-state="${t.state==='EXPLICIT'?'ready':'open'}">${esc(t.state==='EXPLICIT'?tr('Target context established','目标时间已建立'):tr('Current timing not selected','当前时间未选择'))}</span></header>${t.state!=='EXPLICIT'?`<aside class="cx-bazi-professional-boundary"><strong>${esc(tr('No current date was inferred','没有替你推断“今天”'))}</strong><p>${esc(tr('You did not provide a complete BaZi target date, time and timezone. The full Da Yun sequence remains readable, while current Da Yun / Liu Nian stays unavailable. Browser date and timezone are not substituted.','你没有提供完整的八字目标日期、时间与时区。完整大运序列仍可阅读，但当前大运／流年保持不可用；系统不会拿浏览器日期或时区替代。'))}</p></aside>`:`<div class="cx-bazi-timing-now"><article><small>${esc(tr('Current Da Yun','当前大运'))}</small><strong>${esc(current?`${current.pillar?.stem?.zh||''}${current.pillar?.branch?.zh||''}`:'—')}</strong><span>${esc(current?`${current.startAge}–${current.endAge} · ${current.stemTenGod?.zh||''}`:'—')}</span></article><article><small>${esc(tr('Liu Nian','流年'))}</small><strong>${esc(annual?`${annual.stem?.zh||''}${annual.branch?.zh||''}`:'—')}</strong><span>${esc(annual?`${annual.year} · ${annual.stemTenGod?.zh||''}`:'—')}</span></article></div>`}<section class="cx-bazi-dayun-section"><header><h4>${esc(tr('Da Yun timeline','大运时间轴'))}</h4><p>${esc(tr('All cycles come from the birth-time calculation. The highlighted cycle appears only when you choose a target time.','全部大运来自出生时间计算；只有选择明确目标时间时才标出对应的大运。'))}</p></header><div class="cx-bazi-dayun-timeline">${arr(t.allDaYun).map(c=>`<article${current?.cycleNumber===c.cycleNumber?' data-current="true"':''}><small>${esc(tr(`Cycle ${c.cycleNumber}`,`第 ${c.cycleNumber} 运`))}</small><strong>${esc(`${c.pillar?.stem?.zh||''}${c.pillar?.branch?.zh||''}`)}</strong><span>${esc(`${c.startAge}–${c.endAge}`)}</span><em>${esc(c.stemTenGod?.zh||'')}</em></article>`).join('')}</div></section>${t.state==='EXPLICIT'?`<section class="cx-bazi-interaction-section"><header><h4>${esc(tr('Interaction layers','结构互动'))}</h4><p>${esc(tr('Each layer stays traceable to natal, Da Yun or Liu Nian. A combination being present does not mean transformation is established.','每项互动都保留原局、大运或流年的来源；出现组合不等于已经化成。'))}</p></header><div class="cx-bazi-interaction-grid"><article><h5>${esc(tr('Natal × Da Yun','原局 × 大运'))}</h5>${interactionList(ix.currentDaYunToNatal,tr('No additional interaction established.','没有建立额外互动。'))}</article><article><h5>${esc(tr('Natal × Liu Nian','原局 × 流年'))}</h5>${interactionList(ix.liuNianToNatal,tr('No additional interaction established.','没有建立额外互动。'))}</article><article><h5>${esc(tr('Da Yun × Liu Nian','大运 × 流年'))}</h5>${interactionList(ix.liuNianToCurrentDaYun,tr('No additional interaction established.','没有建立额外互动。'))}</article><article><h5>${esc(tr('Natal × Da Yun × Liu Nian','原局 × 大运 × 流年'))}</h5>${arr(ix.crossLayerGroups).length?`<ul>${arr(ix.crossLayerGroups).map(g=>`<li><strong>${esc(relation(g.type))}</strong><span>${esc(memberText(g.members,g.type))}</span><small>${esc(g.transformationEstablished?tr('Transformation established in the current timing calculation','当前时间结构中已建立转化'):tr('Structure present ≠ transformation established','组合出现 ≠ 已经化成'))}</small></li>`).join('')}</ul>`:`<p class="cx-bazi-muted">${esc(tr('No three-layer group established.','没有建立三层组合。'))}</p>`}</article></div></section>`:''}</section>`;
}


export function renderBaziCustomerSafeStructureGraph(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const graph=product?.professionalModules?.customerSafeGraph;if(graph?.schemaVersion!=='PHI-OS-PPR-C1-BAZI-CUSTOMER-SAFE-STRUCTURE-GRAPH-v1.0.0')return '';
 const byKey=new Map(arr(graph.nodes).map(n=>[n.nodeKey,n]));
 const root=byKey.get('CHART'),foundation=byKey.get('FOUNDATION'),relationships=byKey.get('RELATIONSHIPS'),pattern=byKey.get('PATTERN');
 const schools=['SCHOOL_ZIPING','SCHOOL_TIYONG','SCHOOL_TIAOHOU'].map(k=>byKey.get(k)).filter(Boolean),dayun=byKey.get('DA_YUN'),liunian=byKey.get('LIU_NIAN'),open=byKey.get('OPEN_BOUNDARIES');
 return `<section class="cx-bazi-customer-safe-graph${embedded?' cx-bazi-customer-safe-graph--embedded':''}" data-ppr-bazi-customer-safe-graph="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('WHOLE-CHART STRUCTURE MAP','整盘结构关系图'))}</p><h3>${esc(tr('See how foundation, relationships, pattern, schools and timing belong to one chart.','把命局基础、干支关系、格局、学派与时间层放在一张图里看。'))}</h3><p>${esc(tr('The lines show reading context: one part changes how another part is understood, but the diagram is not a causal or probability chart.','连线表示阅读时要彼此参照：一个层次会改变另一个层次的理解方式，但它不是因果图或概率图。'))}</p></div></header><div class="cx-bazi-graph-canvas">${root?`<div class="cx-bazi-graph-root">${graphCard(root)}</div>`:''}<div class="cx-bazi-graph-spine">${[foundation,relationships,pattern].filter(Boolean).map(graphCard).join('')}</div><div class="cx-bazi-graph-branches"><section><header><span>${esc(tr('School views','分学派视角'))}</span></header><div>${schools.map(graphCard).join('')}</div></section><section><header><span>${esc(tr('Timing layers','时间层'))}</span></header><div>${[dayun,liunian].filter(Boolean).map(graphCard).join('')}</div></section></div>${open?`<div class="cx-bazi-graph-open">${graphCard(open)}</div>`:''}</div><footer class="cx-bazi-graph-legend"><span><i data-kind="confirmed"></i>${esc(tr('Confirmed','已确认'))}</span><span><i data-kind="school"></i>${esc(tr('Different school readings','存在不同学派解释'))}</span><span><i data-kind="open"></i>${esc(tr('No strong conclusion yet','暂不作强判断'))}</span></footer></section>`;
}

function installBaziCustomerSafeGraphTab(product){
 if(typeof document==='undefined'||typeof queueMicrotask!=='function')return;
 queueMicrotask(()=>{const node=document.querySelector('[data-cx-personal-graphs]');if(!node)return;const html=renderBaziCustomerSafeStructureGraph(product);if(!html)return;const existing=node.querySelector('[data-ppr-bazi-customer-safe-graph]');if(existing){existing.outerHTML=html;return}const onlyPlaceholder=node.children.length===1&&node.firstElementChild?.classList.contains('cx-p1-empty');if(onlyPlaceholder)node.innerHTML=html;else node.insertAdjacentHTML('afterbegin',html)});
}

const REALITY_QUESTION_COPY={
 FOUNDATION:{title:['Foundation in lived experience','命局基础在现实中如何稳定出现？'],question:['Does this whole-chart foundation stay recognizable across different periods, or only under certain conditions?','这组整盘基础是否在不同阶段都能辨认出来，还是只在特定条件下明显？']},
 RELATIONSHIPS:{title:['Relationship structure in lived experience','哪些关系结构会在现实中反复出现？'],question:['Across different roles and environments, which established relationship patterns repeat, and where do they not?','跨不同角色与环境，哪些已经建立的关系结构会重复出现，又有哪些场景并不符合？']},
 PATTERN:{title:['Pattern candidates in lived experience','哪些格局候选得到较稳定的现实支持？'],question:['Among the open pattern candidates, which path is repeatedly supported by lived experience, which appears only conditionally, and what argues against promoting one too early?','在仍开放的格局候选中，哪条路径得到较稳定的现实支持，哪条只在特定条件下出现，又有哪些反例提醒我们不要过早定主格？']},
 SCHOOL_ZIPING:{title:['Zi Ping reality check','子平月令视角如何与现实对照？'],question:['When you compare month-command and pattern logic with lived experience, what repeats reliably and what remains conditional?','把月令与格局逻辑放回现实后，哪些表现稳定重复，哪些只在特定条件下成立？']},
 SCHOOL_TIYONG:{title:['Ti-Yong reality check','体用与平衡如何与现实对照？'],question:['Where does the chart’s weighting and balance feel structurally consistent, and where does lived experience show a different balance?','整盘偏重与平衡在哪些现实情境中较稳定，又有哪些经验显示出不同的平衡？']},
 SCHOOL_TIAOHOU:{title:['Climate-adjustment reality check','寒暖燥湿如何与现实对照？'],question:['Under what environments or phases does the cold/warm/dry/wet dimension become noticeable, and when does it not?','寒暖燥湿这一维度通常在什么环境或阶段变得明显，又在什么情况下并不明显？']},
 TIMING:{title:['Timing correspondence','当前时间激活有没有现实对应？'],question:['Around the selected Da Yun / Liu Nian context, is there a recognizable change in the themes already present in the natal chart?','在所选大运／流年的时间窗口附近，原局已有主题是否出现了可以辨认的变化？']}
};
function realityQuestionCopy(key){return REALITY_QUESTION_COPY[key]||{title:['Reality comparison','现实对照'],question:['What repeats, what depends on context, and what contradicts the reading?','哪些会重复出现，哪些依赖情境，又有哪些现实反例？']}}
const REALITY_PROBE_COPY={
 FOUNDATION:[['Repeated pattern — does the whole-chart foundation remain recognizable across different periods?','重复出现——这组整盘基础是否在不同阶段仍能辨认？'],['Context specificity — which environments make this foundation clearer or less visible?','情境限定——哪些环境会让这组基础更清楚，哪些环境会让它不明显？'],['What does not fit — what recurring experience does not fit this foundation?','不符合之处——有哪些反复出现的现实经验并不符合这组基础？']],
 RELATIONSHIPS:[['Repeated pattern — which established relationship structures recur across different roles?','重复出现——哪些已经建立的关系结构会跨不同角色反复出现？'],['Context specificity — which relationship pattern appears only with certain people or pressures?','情境限定——哪些关系模式只会在特定对象或压力下出现？'],['What does not fit — where do your actual relationships show the opposite structure?','不符合之处——哪些真实关系呈现了与读取相反的结构？']],
 PATTERN:[['Repeated pattern — which open pattern candidate receives support across more than one setting?','重复出现——哪条开放中的格局候选在不止一种情境里得到支持？'],['Context specificity — which candidate appears only under a narrow condition?','情境限定——哪条候选只在较窄的条件下出现？'],['What does not fit — what experience argues against promoting a candidate too early?','不符合之处——哪些经验提醒我们还不能过早把某条候选提升为主格？']],
 SCHOOL_ZIPING:[['Repeated pattern — does month-command logic recur across different phases?','重复出现——月令与格局逻辑是否在不同阶段持续出现？'],['Context specificity — under which conditions does the Zi Ping reading become most visible?','情境限定——子平月令视角在什么条件下最明显？'],['What does not fit — where does lived experience not follow the month-command expectation?','不符合之处——哪些现实经验并没有沿着月令预期展开？']],
 SCHOOL_TIYONG:[['Repeated pattern — does the same weighting or balance pattern recur across major situations?','重复出现——相似的整盘偏重或平衡模式是否会在重要情境中重复？'],['Context specificity — when does the chart feel more balanced or more one-sided?','情境限定——什么情况下整盘更平衡，什么情况下偏重更明显？'],['What does not fit — which experience suggests a different weighting from this school view?','不符合之处——哪些经验显示出与体用视角不同的整盘偏重？']],
 SCHOOL_TIAOHOU:[['Repeated pattern — does the climate-adjustment theme recur across seasons or environments?','重复出现——寒暖燥湿主题是否会跨季节或环境重复出现？'],['Context specificity — which surroundings make the climate dimension more noticeable?','情境限定——哪些环境会让寒暖燥湿维度更明显？'],['What does not fit — when does the expected climate tendency not show up at all?','不符合之处——什么情况下预期的调候倾向并没有出现？']],
 TIMING:[['Repeated pattern — during this target window, which natal theme is showing up again?','重复出现——在这个目标时间窗口里，哪项原局主题再次出现？'],['Context specificity — is the activation limited to one role, environment or pressure?','情境限定——这次激活是否只集中在某个角色、环境或压力？'],['What does not fit — what expected activation is absent or moving in the opposite direction?','不符合之处——哪些预期激活没有出现，或者反而朝相反方向发展？']]
};
function realityProbeList(question){const key=String(question?.questionKey||'');const probes=(REALITY_PROBE_COPY[key]||REALITY_PROBE_COPY.FOUNDATION).map(([en,zh])=>tr(en,zh));if(question?.temporalCorrespondenceEnabled)probes.push(tr('Temporal correspondence — around the selected timing window, did an already-present natal theme become more visible, less visible, or simply different?','时间对应——在所选时间窗口附近，原局已有主题是变得更明显、更不明显，还是只是以不同方式出现？'));return probes}
export function renderBaziRealityComparisonSurface(product,{embedded=false}={}){
 if(!isBaziNativeProduct(product))return '';
 ensureBaziSpecialistCss();
 const module=product?.professionalModules?.realityComparison;if(module?.schemaVersion!=='PHI-OS-PPR-C1-BAZI-REALITY-COMPARISON-v1.0.0')return '';
 return `<section class="cx-bazi-reality-comparison${embedded?' cx-bazi-surface--embedded':''}" data-ppr-bazi-reality-comparison="true"><header class="cx-bazi-professional-head"><div><p class="cx-eyebrow">${esc(tr('REALITY COMPARISON','现实对照'))}</p><h3>${esc(tr('One chart theme, one useful reality question.','一个命盘主题，只保留一个真正有用的现实问题。'))}</h3><p>${esc(tr('Use these questions after reading the BaZi interpretation. They help you notice what repeats, what depends on context and what does not fit.','先读完八字解释，再用这些问题回到现实：看哪些会重复、哪些依赖情境，以及哪些地方并不符合。'))}</p></div><span class="cx-personal-status-chip" data-state="ready">${esc(tr(`${module.questionCount} reality questions`,`${module.questionCount} 个现实问题`))}</span></header><div class="cx-bazi-reality-grid">${arr(module.questions).map((q,index)=>{const copy=realityQuestionCopy(q.questionKey);return `<article class="cx-bazi-reality-card" data-question-key="${esc(q.questionKey)}"><header><small>${String(index+1).padStart(2,'0')} · ${esc(customerState(q.resolutionState))}</small><h4>${esc(tr(copy.title[0],copy.title[1]))}</h4></header><blockquote>${esc(tr(copy.question[0],copy.question[1]))}</blockquote><ul>${realityProbeList(q).map(x=>`<li>${esc(customerText(x))}</li>`).join('')}</ul></article>`}).join('')}</div><aside class="cx-bazi-professional-boundary"><strong>${esc(tr('How to use this section','这一章怎么用'))}</strong><p>${esc(tr('Agreement or disagreement helps you examine the reading; it does not change the Four-Pillar calculation by itself.','现实经验无论符合或不符合，都用来帮助你理解这份解读；它本身不会改写四柱计算。'))}</p></aside></section>`;
}

function reportSection(section){
 const head=`<header><span>${esc(customerState(section?.state))}</span><h3>${esc(customerText(section?.title||section?.code||''))}</h3>${section?.dek?`<p>${esc(customerText(section.dek))}</p>`:''}</header>`;
 if(section?.code==='SCHOOLS')return `<section class="cx-native-section" data-section="SCHOOLS">${head}<div class="cx-native-school-grid">${arr(section.blocks).map(b=>`<article><strong>${esc(customerText(b.title||''))}</strong><span>${esc(tr('School-qualified view','分学派读取'))}</span><p>${esc(customerText(b.text||''))}</p></article>`).join('')}</div></section>`;
 if(section?.code==='OPEN')return `<section class="cx-native-section cx-bazi-open" data-section="OPEN">${head}<ul>${arr(section.items).map(x=>`<li>${esc(customerText(x))}</li>`).join('')}</ul></section>`;
 return `<section class="cx-native-section" data-section="${esc(section?.code||'')}">${head}${arr(section?.paragraphs).map(p=>`<p>${esc(customerText(p))}</p>`).join('')}</section>`;
}

